import re

def valid_seat(s):
    return re.match(r"\d{1,2}[A-F]", s) is not None

def second_largest(nums):
    s = sorted(set(nums), reverse=True)
    return s[1] if len(s) > 1 else None

def first_over(xs, t):
    for i, x in enumerate(xs):
        if x >= t:
            return i
    return -1
